using UnityEngine;

// 1인칭 점프맵: 카메라가 주인공의 눈이 돼요.
// 쓰인 코드: GetComponent<Rigidbody>() · velocity · isGrounded · OnTriggerEnter(Collider) · other.tag · UIScreen.SetText · Time.time
// WASD · 방향키: 걷기 · Space: 점프 · 마우스를 누른 채 끌기 또는 Q · E / R · F: 둘러보기
// 떨어지면 마지막 체크포인트에서 다시 시작해요.
public class FirstPersonJumper : MonoBehaviour
{
    [Header("이동")]
    public float moveSpeed = 5f;
    public float jumpPower = 7f;
    [Tooltip("이 높이보다 아래로 떨어지면 다시 시작")]
    public float fallY = -10f;

    [Header("시점")]
    public float eyeHeight = 0.6f;
    public float mouseSensitivity = 3f;
    public float keyTurnSpeed = 110f;

    Rigidbody rb;
    Transform cam;
    float yaw;
    float pitch = 8f;
    Vector3 respawn;
    int checkpoints;
    int falls;
    float startTime;
    bool finished;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        if (transform.childCount > 0) cam = transform.GetChild(0);
        yaw = transform.eulerAngles.y;
        respawn = transform.position;
        startTime = Time.time;
    }

    void Update()
    {
        // 둘러보기 (가로: yaw · 세로: pitch)
        if (Input.GetMouseButton(0) || Input.GetMouseButton(1))
        {
            yaw += Input.GetAxis("Mouse X") * mouseSensitivity;
            pitch -= Input.GetAxis("Mouse Y") * mouseSensitivity;
        }
        if (Input.GetKey(KeyCode.Q)) yaw -= keyTurnSpeed * Time.deltaTime;
        if (Input.GetKey(KeyCode.E)) yaw += keyTurnSpeed * Time.deltaTime;
        if (Input.GetKey(KeyCode.R)) pitch -= keyTurnSpeed * 0.6f * Time.deltaTime;
        if (Input.GetKey(KeyCode.F)) pitch += keyTurnSpeed * 0.6f * Time.deltaTime;
        pitch = Mathf.Clamp(pitch, -70f, 80f);
        transform.eulerAngles = new Vector3(0, yaw, 0);

        // 보는 쪽으로 걷기
        float r = yaw * Mathf.Deg2Rad;
        Vector3 forward = new Vector3(Mathf.Sin(r), 0, Mathf.Cos(r));
        Vector3 right = new Vector3(Mathf.Cos(r), 0, -Mathf.Sin(r));
        Vector3 move = right * Input.GetAxisRaw("Horizontal") + forward * Input.GetAxisRaw("Vertical");
        if (move.magnitude > 1f) move = move.normalized;
        Vector3 v = rb.velocity;
        rb.velocity = new Vector3(move.x * moveSpeed, v.y, move.z * moveSpeed);
        if (rb.isGrounded && Input.GetButtonDown("Jump"))
        {
            rb.velocity = new Vector3(rb.velocity.x, jumpPower, rb.velocity.z);
            Sfx("점프");
        }

        // 떨어지면 체크포인트로
        if (transform.position.y < fallY)
        {
            transform.position = respawn;
            rb.velocity = Vector3.zero;
            falls++;
            Sfx("떨어짐");
            ShowProgress();
        }

        // 눈 높이에 카메라
        if (cam != null)
        {
            cam.position = transform.position + new Vector3(0, eyeHeight, 0);
            cam.eulerAngles = new Vector3(pitch, yaw, 0);
        }
        if (!finished) UIScreen.SetText("기록", "시간", (Time.time - startTime).ToString("0.0") + "초");
    }

    void OnTriggerEnter(Collider other)
    {
        if (other.tag == "Checkpoint")
        {
            Vector3 p = other.transform.position;
            Vector3 next = new Vector3(p.x, p.y + 1.2f, p.z);
            if (Vector3.Distance(next, respawn) > 0.5f)
            {
                respawn = next;
                checkpoints++;
                Sfx("체크포인트");
                ShowProgress();
                Debug.Log("체크포인트 " + checkpoints + "!");
            }
        }
        else if (other.tag == "Goal" && !finished)
        {
            finished = true;
            float t = Time.time - startTime;
            UIScreen.SetText("완료", "기록", t.ToString("0.0") + "초 · 떨어짐 " + falls + "번");
            UIScreen.Show("완료");
            Sfx("골인 팡파르");
        }
    }

    void ShowProgress()
    {
        UIScreen.SetText("기록", "진행", "체크포인트 " + checkpoints + " / 3 · 떨어짐 " + falls);
    }

    // ▼ 직접 만든 메서드: 씬의 「효과음」 오브젝트에 붙은 오디오 소스로 이름이 같은 오디오 클립을 겹쳐 재생해요
    //   PlayOneShot("클립 이름")은 지금 나는 소리를 끊지 않고 하나 더 겹쳐서 틀어요
    void Sfx(string clip)
    {
        GameObject.Find("효과음").GetComponent<AudioSource>().PlayOneShot(clip);
    }
}

using UnityEngine;

// 빙글빙글 도는 장식 (트로피 · 체크포인트 깃발)
public class Spinner : MonoBehaviour
{
    public float speed = 90f;     // 1초에 도는 각도
    void Update()
    {
        transform.Rotate(0, speed * Time.deltaTime, 0);
    }
}

using UnityEngine;

// 오르내리는 발판: 시작 높이에서 height 만큼 천천히 오르내려요.
// 쓰인 코드: Mathf.PingPong · transform.position
public class Lift : MonoBehaviour
{
    public float height = 3f;
    public float speed = 0.8f;
    float baseY;
    void Start() { baseY = transform.position.y; }
    void Update()
    {
        Vector3 p = transform.position;
        transform.position = new Vector3(p.x, baseY + Mathf.PingPong(Time.time * speed, height), p.z);
    }
}
